"use client"
import { Card } from "@/components/ui/card";
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";

const patient = {
  name: "John Doe",
  avatar: null,
  age: 32,
  gender: "Male",
};

const history = [
  {
    id: 1,
    date: "2024-06-10",
    type: "Video",
    status: "completed",
    notes: "Follow-up on blood pressure medication. Patient is responding well.",
  },
  {
    id: 2,
    date: "2024-05-15",
    type: "In-person",
    status: "completed",
    notes: "Annual physical exam. All vitals normal.",
  },
  {
    id: 3,
    date: "2024-04-01",
    type: "Video",
    status: "cancelled",
    notes: "Appointment cancelled by patient due to scheduling conflict.",
  },
];

function HistoryItem({ item }) {
  return (
    <Card className="rounded-xl p-4 shadow flex flex-col gap-2 text-gray-700 hover:bg-gray-50 transition">
      <div className="flex items-center gap-3">
        <Badge className="mr-2">{item.date}</Badge>
        <Badge variant="outline">{item.type}</Badge>
        <Badge variant={item.status === "completed" ? "default" : "destructive"}>
          {item.status.charAt(0).toUpperCase() + item.status.slice(1)}
        </Badge>
      </div>
      <div className="text-sm text-gray-600 mt-1">{item.notes}</div>
    </Card>
  );
}

export default function ViewHistoryPage() {
  const { id } = useParams();
  const router = useRouter();
  const [patient, setPatient] = useState(null);
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;

    const fetchData = async () => {
      try {
        const data = await getPatientHistory(id);
        setPatient(data.patient);
        setHistory(data.history);
      } catch (err) {
        console.error("Error fetching patient history:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [id]);

  if (loading) return <div className="text-center text-gray-500 py-8">Loading patient history...</div>;
  if (!patient) return <div className="text-center text-gray-400 py-8">Patient not found.</div>;


  return (
    <div className="max-w-2xl mx-auto py-8">
      <h1 className="text-2xl font-bold mb-6">Patient Profile</h1>
      <Card className="flex items-center gap-4 p-4 mb-8 rounded-xl shadow">
        <Avatar name={patient.name} src={patient.avatar} className="w-16 h-16" />
        <div>
          <div className="font-semibold text-lg">{patient.name}</div>
          <div className="text-gray-500 text-sm">Age: {patient.age} | Gender: {patient.gender}</div>
        </div>
        <div className="flex gap-2 mt-auto ">
          <Button className="rounded-lg" size="sm">Message</Button>
          <Button className="rounded-lg" size="sm" onClick={()=>router.push("/doctor/prescription")}>Add Prescription</Button>
        </div>
      </Card>
      <div className="flex flex-col gap-4">
        {history.length ? history.map((item) => (
          <HistoryItem key={item.id} item={item} />
        )) : <div className="text-center text-gray-400">No history found.</div>}
      </div>
    </div>
  );
} 